islands.s4Code:
import { mountComponent, type Component } from "@nexa/reactivity";

interface ItemProps { label: string }
const Item: Component<ItemProps> = (el, props) => {
    el.textContent = props.label;
};

interface ListProps { labels: string[] }
const List: Component<ListProps> = (el, props, ctx) => {
    for (const label of props.labels) {
        const li = document.createElement("li");
        el.appendChild(li);
        ctx.mount(Item, li, { label });
    }
};

export default function mount(el: Element, props: Record<string, unknown>) {
    return mountComponent(List, el, { labels: props.labels as string[] });
}

islands.s5Code:
// src/islands/markdownPreview.island.ts
import { marked } from "marked"; // import normal, se bundlea con esbuild

export default function mount(el: Element, props: Record<string, unknown>) {
    const textarea = document.createElement("textarea");
    textarea.value = typeof props.initial === "string" ? props.initial : "";
    const preview = document.createElement("div");

    const render = () => { preview.innerHTML = marked.parse(textarea.value) as string; };
    textarea.addEventListener("input", render);
    el.append(textarea, preview);
    render();
}

// src/pages/index.tsx
<div
    data-nexa-island="markdownPreview"
    data-nexa-strategy="load"
    data-nexa-props={{ initial: "# Hola\n\nEsto es *Markdown* real." }}
>
    <p>Cargando editor…</p>
</div>

// nexa.toml — este [imports] es para localizar el ARCHIVO de la isla ya
// bundleado, no la librería marked (esa ya quedó adentro del bundle)
[imports]
markdownPreview = "/vendor/markdown-preview-island.js"

